export function isValidId(value) {
  return typeof value === 'string' ? /^\d{1,9}$/.test(value) : Number.isInteger(value) && value > 0;
}

/** Parse a positive integer id from route params / form data; returns null if invalid. */
export function toId(value) {
  if (value === null || value === undefined) return null;
  const str = String(value).trim();
  if (!/^\d{1,9}$/.test(str)) return null;
  const n = parseInt(str, 10);
  return n > 0 ? n : null;
}

/** Verify that an image path was generated by the ARTHIVE local file upload handler. */
export function isUploadedImagePath(value) {
  if (typeof value !== 'string') return false;
  return /^\/uploads\/[a-zA-Z0-9._-]+\.(jpe?g|png|webp)$/i.test(value.trim());
}
